    const poolCanAct = () => !poolS.awaitStart && !poolS.handoff && !poolCpuTurn() && !poolRemoteTurn() && poolS.phase !== 'over' && poolS.phase !== 'choice' && !poolS.confirm && !poolS.sheet.open && !poolTourBlocked();

    // ── The CPU's turn ────────────────────────────────────────────────
